from h34 import *
M=mcq;F=tf;S=short;N=num
z='<rect x="0" y="40" width="720" height="110" fill="#555"/><line x1="0" y1="95" x2="720" y2="95" stroke="#fff" stroke-width="3" stroke-dasharray="20 14"/>'
for i in range(7): z+=f'<rect x="{250+i*34}" y="40" width="20" height="110" fill="#fff"/>'
z+='<rect x="0" y="0" width="720" height="40" fill="#cfe8c4"/><rect x="0" y="150" width="720" height="40" fill="#cfe8c4"/><text x="80" y="25">Footpath: walk here</text><text x="470" y="180">Zebra crossing: look right, left, right</text><circle cx="640" cy="18" r="10" fill="#3a9d5d"/><circle cx="610" cy="18" r="10" fill="#aaa"/><text x="560" y="22" text-anchor="end">Wait for green</text>'
svgfile('c4en-road-safety.svg',720,190,z)
chapter(4,'english','be-smart-be-safe','Be Smart, Be Safe',
 ('A letter from the traffic police','The traffic police of Bharat write a letter to children with six simple rules for staying safe on the road. In this chapter you will read the letter, learn words like pedestrian and reflective, recognise road signs, sort safe and unsafe actions, learn about countable and uncountable nouns, and write a thank-you letter to the traffic police.'),
 [('The letter',['The traffic police write to children who reach school on foot, by bicycle or by bus.','Roads are often busy with traffic and at times dangerous, so the police want to share tips to cross and walk safely.','If everyone follows the simple rules, accidents can be avoided, and the roads become safer for everyone.']),
  ('Rules 1 to 3',['Rule 1: always use the zebra crossing, the black and white stripes on the road. Look right, then left, then right again, and cross only when it is safe.','Rule 2: follow traffic lights. On busy roads wait for the pedestrian signal to turn green before crossing, and never run, but walk calmly.','Rule 3: walk on the footpath, which is meant for pedestrians, and stay away from moving vehicles.']),
  ('Rules 4 to 6',['Rule 4: hold an adult\'s hand when you walk near the road, especially while crossing.','Rule 5: use reflective stickers if you walk in the evening, so drivers can see you clearly in the dark.','Rule 6: be alert. Do not play or get distracted near roads, and avoid headphones or mobile phones near traffic, because they stop you hearing the traffic sounds.','Wearing dark clothes in the evening makes you harder to see, so wear bright clothes or reflective stickers.']),
  ('New words',['A pedestrian is a person who walks on the road or footpath.','A footpath is the part of the road kept for people to walk on. Reflective things shine back light so they can be seen in the dark.','To distract means to take your attention away from something important.']),
  ('Road signs',['Signs on the road give us messages without words. Some tell us what to do and some tell us what not to do.','School ahead warns drivers to slow down. No honking means do not blow the horn. Right turn and U-turn show where we can turn. No left turn means we may not turn left.','Drive slow and Danger ahead are warnings. There are also signs for a restroom for ladies or gents and for a person with a disability.','Learn to read the signs, because they keep everyone safe.']),
  ('Safe and unsafe',['Looking right and left before crossing, crossing at a zebra crossing and walking on the footpath are safe.','Playing on the road and listening to loud music on the road are unsafe.','Before you do anything near the road, ask: could this get me hurt?']),
  ('Countable and uncountable nouns',['A noun is a naming word for a person, place, thing or idea.','Countable nouns can be counted, like apples, buses, chairs, helmets and cars. They have a plural form.','Uncountable nouns cannot be counted one by one, like water, rice, air, traffic and pollution. They usually have no plural.','We can count them by using a container or a measure, like a bottle of milk, a bowl of rice or two drops of oil.','Bananas, biscuits, tomatoes, sandwiches, chocolates and potatoes are countable. Lemonade, flour, curd, coffee and tomato ketchup are uncountable.']),
  ('Writing to the traffic police',['A letter to the traffic police can thank them, say you have read their letter, and promise to follow the rules.','For example: Thank you for keeping us safe. I will use the zebra crossing, hold an adult\'s hand and walk on the footpath.','End the letter with your name and grade.'])],
 [('Is this safe or unsafe: listening to loud music while crossing the road?',[('Think whether you can still hear the traffic.','Loud music covers the sounds of horns and engines.'),('So you may not hear a vehicle coming.','Being alert is Rule 6.'),('It is unsafe.','Take off the headphones near roads.')]),
  ('Is the noun countable or uncountable: water?',[('Can we count water one by one?','We cannot say one water, two waters.'),('We count it by containers, like a glass of water.','The container is countable, the water is not.'),('So water is uncountable.','Rice and air are also uncountable.')])],
 ('Tell the six road safety rules in your own words and say why each matters.',['Zebra crossing','Traffic lights','Footpath','Hold an adult\'s hand','Reflective stickers','Be alert'],['It is safe to run across the road','Headphones keep us safe near roads']),
 ['Use the zebra crossing and look right, left, then right again.','Follow traffic lights and walk on the footpath.','Hold an adult\'s hand and use reflective stickers in the dark.','Do not use headphones or play near traffic.','Countable nouns can be counted; uncountable nouns cannot.'],
 [M('1',1,'What should you do before crossing a road?','Stop and look right, left, then right again',[('Run quickly','Running is unsafe'),('Close your eyes','You must look')],'Look and cross only when it is safe.'),
  M('2',1,'Where should you walk near the road?','On the footpath',[('On the road','Vehicles move there'),('Between vehicles','That is dangerous')],'Footpaths are meant for pedestrians.'),
  M('3',1,'Why should you avoid headphones near traffic?','They can distract you from traffic sounds',[('They look bad','The reason is safety'),('They make you run','Not the reason')],'You must hear the vehicles.'),
  M('4',1,'Why hold an adult\'s hand while crossing?','To be safe',[('To walk faster','Not the reason'),('To carry things','Not the reason')],'An adult can guide you safely.'),
  F('5',1,'Wearing dark clothes in the evening makes you more visible.',False,'Reflective or bright clothes are easier to see.'),
  F('6',1,'It is safe to play near the road.',False,'Roads are for vehicles and walkers.'),
  M('7',2,'Which is a countable noun?','Bus',[('Water','Water is uncountable'),('Air','Air is uncountable')],'We can say one bus, two buses.'),
  M('8',2,'Which is an uncountable noun?','Rice',[('Chair','Chairs can be counted'),('Helmet','Helmets can be counted')],'We do not count rice one by one.'),
  M('9',2,'A person who walks on the road is a ___.','pedestrian',[('driver','Driver drives'),('rider','Rider rides')],'A pedestrian walks.'),
  M('10',2,'Reflective stickers help drivers to ___.','see you in the dark',[('hear you','They help sight'),('smell you','Not related')],'They shine in the headlights.'),
  M('11',2,'What does a zebra crossing look like?','Black and white stripes on the road',[('Red lights','Lights are different'),('A bridge','Not the zebra crossing')],'It looks like stripes.'),
  S('12',3,'Who wrote the letter in the lesson?',['traffic police','the traffic police','traffic police of bharat'],'The traffic police wrote the letter.')],
 svgs=[('c4en-road-safety','A road with a zebra crossing, footpaths and a traffic signal.','Walk on the footpath, cross at the zebra crossing and wait for green.')],
 keep=['zebra crossing','pedestrian'])
